  "bounded contexts": {
    "...": {
      "derived from": "...",
      "objects": [
        "...",
        "..."
      ],
      "name changes": []
    },
    "...": {
      "derived from": "...",
      "objects": [
        "...",
        "...",
        "..."
      ],
      "name changes": [
        "... -> ..."
      ]
    }
  }
}
```

